"""Static business-intelligence dashboards generated from the published warehouse (SYNTHETIC DATA on every page).

    python -m nasha_lab.warehouse.dashboards --db wh.db --out dashboards/
Seven pages: executive, store operations, product profitability, inventory and waste, loyalty and retention, merchandise, experiments.
The generator refuses to run unless warehouse_status is 'published'. Charts are inline SVG with text alternatives (data tables); no JavaScript, no external requests."""
import argparse
import html
import json
import sys
from pathlib import Path

import pandas as pd

from . import analytics, db, experiments

E = html.escape
C = dict(bg="#141110", card="#241E1B", ink="#F3ECDD", mut="#BDB3A3", rule="#3a312c", gold="#E8870E", herb="#9DBB5B", hib="#D4547C", ind="#7C8DD6", lime="#E4DAC6")
CSS = f"""
:root{{color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:{C['bg']};color:{C['ink']};font:16px/1.55 Inter,system-ui,-apple-system,"Segoe UI",sans-serif}}
a{{color:{C['gold']}}}.wrap{{max-width:1180px;margin:0 auto;padding:0 20px}}header{{border-bottom:1px solid {C['rule']}}}
.banner{{background:#3a2a10;color:#FFD9A0;padding:10px 20px;font-size:14px;border-bottom:1px solid {C['gold']}}}
nav{{display:flex;flex-wrap:wrap;gap:6px 18px;padding:14px 0}}nav a{{text-decoration:none;color:{C['ink']};padding:4px 0}}nav a[aria-current=page]{{border-bottom:2px solid {C['gold']}}}
h1{{font:400 2.2rem/1.1 "Instrument Serif",Georgia,serif;margin:22px 0 4px}}h2{{font:400 1.45rem/1.2 "Instrument Serif",Georgia,serif;margin:34px 0 8px}}.sub{{color:{C['mut']};margin:0 0 18px}}
.tiles{{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}}.tile{{background:{C['card']};border:1px solid {C['rule']};padding:14px}}
.tile b{{display:block;font-size:1.7rem;font-weight:600}}.tile span{{color:{C['mut']};font-size:13px}}.card{{background:{C['card']};border:1px solid {C['rule']};padding:16px;margin:12px 0;overflow-x:auto}}
table{{border-collapse:collapse;width:100%;font-size:14px}}th,td{{text-align:right;padding:6px 10px;border-bottom:1px solid {C['rule']}}}th:first-child,td:first-child{{text-align:left}}th{{color:{C['mut']};font-weight:600}}
svg{{max-width:100%;height:auto}}.note{{color:{C['mut']};font-size:13px}}details{{margin-top:8px}}summary{{cursor:pointer;color:{C['mut']}}}footer{{border-top:1px solid {C['rule']};margin-top:40px;padding:18px 0;color:{C['mut']};font-size:13px}}
.pos{{color:{C['herb']}}}.neg{{color:{C['hib']}}}
"""
PAGES = [("index.html", "Executive"), ("stores.html", "Store operations"), ("products.html", "Product profitability"), ("inventory.html", "Inventory and waste"),
         ("loyalty.html", "Loyalty and retention"), ("merch.html", "Merchandise"), ("experiments.html", "Experiments")]
BANNER = "SYNTHETIC DATA. Generated by a deterministic simulation. Prices, wages and costs are placeholders and volumes are uncalibrated. These are not NASHA results: NASHA is a concept and no business operates."


def usd(cents, compact=False):
    v = cents / 100
    if compact and abs(v) >= 1e6:
        return f"${v / 1e6:,.1f}M"
    if compact and abs(v) >= 1e3:
        return f"${v / 1e3:,.0f}k"
    return f"${v:,.2f}"


def line_chart(title, labels, series, fmt=lambda v: f"{v:,.0f}", h=240):
    """series: [(name, values, colour)]"""
    w, pad_l, pad_b, pad_t = 900, 64, 34, 14
    vals = [v for _, vs, _ in series for v in vs if v is not None]
    lo, hi = (0, max(vals) * 1.08) if min(vals) >= 0 else (min(vals) * 1.08, max(vals) * 1.08)
    sx = lambda i: pad_l + (w - pad_l - 14) * i / max(1, len(labels) - 1)
    sy = lambda v: pad_t + (h - pad_t - pad_b) * (1 - (v - lo) / (hi - lo or 1))
    g = [f'<line x1="{pad_l}" x2="{w - 14}" y1="{sy(lo + (hi - lo) * k / 4):.1f}" y2="{sy(lo + (hi - lo) * k / 4):.1f}" stroke="{C["rule"]}"/><text x="{pad_l - 8}" y="{sy(lo + (hi - lo) * k / 4) + 4:.1f}" text-anchor="end" fill="{C["mut"]}" font-size="12">{fmt(lo + (hi - lo) * k / 4)}</text>' for k in range(5)]
    for i in range(0, len(labels), max(1, len(labels) // 8)):
        g.append(f'<text x="{sx(i):.1f}" y="{h - 10}" text-anchor="{"end" if i >= len(labels) - 1 else "middle"}" fill="{C["mut"]}" font-size="12">{E(labels[i])}</text>')
    for name, vs, col in series:
        pts = " ".join(f"{sx(i):.1f},{sy(v):.1f}" for i, v in enumerate(vs) if v is not None)
        g.append(f'<polyline points="{pts}" fill="none" stroke="{col}" stroke-width="2.5" stroke-linejoin="round"/>')
    leg = "".join(f'<tspan fill="{c}">● {E(n)}  </tspan>' for n, _, c in series)
    rows = "".join(f"<tr><td>{E(l)}</td>" + "".join(f"<td>{fmt(vs[i]) if vs[i] is not None else ''}</td>" for _, vs, _ in series) + "</tr>" for i, l in enumerate(labels))
    head = "".join(f"<th>{E(n)}</th>" for n, _, _ in series)
    return (f'<div class="card"><svg viewBox="0 0 {w} {h + 20}" role="img" aria-label="{E(title)}"><title>{E(title)}</title><text x="{pad_l}" y="12" font-size="13" fill="{C["ink"]}">{E(title)}  {leg}</text><g transform="translate(0,16)">{"".join(g)}</g></svg>'
            f'<details><summary>Data table</summary><table><tr><th>Month</th>{head}</tr>{rows}</table></details></div>')


def bar_chart(title, items, fmt=lambda v: f"{v:,.0f}", colour=C["gold"], w=900):
    mx = max([v for _, v in items] + [1e-9])
    rows = len(items)
    h = 30 * rows + 10
    g = []
    for i, (name, v) in enumerate(items):
        y = 6 + i * 30
        bw = (w - 280) * max(v, 0) / mx
        g.append(f'<text x="196" y="{y + 16}" text-anchor="end" fill="{C["ink"]}" font-size="13">{E(str(name))[:30]}</text><rect x="204" y="{y + 3}" width="{bw:.1f}" height="18" fill="{colour}"/><text x="{210 + bw:.1f}" y="{y + 17}" fill="{C["mut"]}" font-size="12">{fmt(v)}</text>')
    t = "".join(f"<tr><td>{E(str(n))}</td><td>{fmt(v)}</td></tr>" for n, v in items)
    return f'<div class="card"><div style="margin-bottom:6px">{E(title)}</div><svg viewBox="0 0 {w} {h}" role="img" aria-label="{E(title)}"><title>{E(title)}</title>{"".join(g)}</svg><details><summary>Data table</summary><table>{t}</table></details></div>'


def heatmap(title, df, fmt=lambda v: f"{v * 100:.0f}%"):
    cols = list(df.columns)[:13]
    cw, ch, lw = 56, 24, 80
    w, h = lw + cw * len(cols) + 10, 30 + ch * len(df)
    g = [f'<text x="{lw + cw * j + cw / 2}" y="16" text-anchor="middle" fill="{C["mut"]}" font-size="12">m+{c}</text>' for j, c in enumerate(cols)]
    for i, (idx, row) in enumerate(df.iterrows()):
        g.append(f'<text x="{lw - 8}" y="{30 + i * ch + 16}" text-anchor="end" fill="{C["mut"]}" font-size="12">{E(str(idx))}</text>')
        for j, c in enumerate(cols):
            v = row[c]
            if pd.notna(v):
                a = min(1, v * 2.2)
                g.append(f'<rect x="{lw + cw * j}" y="{30 + i * ch}" width="{cw - 2}" height="{ch - 2}" fill="{C["gold"]}" fill-opacity="{0.12 + 0.88 * a:.2f}"/><text x="{lw + cw * j + cw / 2}" y="{30 + i * ch + 16}" text-anchor="middle" fill="#fff" font-size="11">{fmt(v)}</text>')
    return f'<div class="card"><div>{E(title)}</div><svg viewBox="0 0 {w} {h}" role="img" aria-label="{E(title)}"><title>{E(title)}</title>{"".join(g)}</svg></div>'


def table(df, fmts=None):
    fmts = fmts or {}
    head = "".join(f"<th>{E(str(c))}</th>" for c in df.columns)
    body = "".join("<tr>" + "".join(f"<td>{E(fmts.get(c, str)(v)) if (isinstance(v, (list, tuple)) or pd.notna(v)) else ''}</td>" for c, v in zip(df.columns, r)) + "</tr>" for r in df.itertuples(index=False, name=None))
    return f'<div class="card"><table><tr>{head}</tr>{body}</table></div>'


def tiles(items):
    return '<div class="tiles">' + "".join(f'<div class="tile"><b>{E(v)}</b><span>{E(k)}</span></div>' for k, v in items) + "</div>"


def page(name, title, sub, body, kpis_note):
    nav = "".join(f'<a href="{f}"{" aria-current=page" if f == name else ""}>{E(t)}</a>' for f, t in PAGES)
    return (f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow">'
            f'<title>{E(title)} · NASHA synthetic enterprise (working name)</title><style>{CSS}</style></head><body><div class="banner" role="note"><strong>{E(BANNER)}</strong></div>'
            f'<header><div class="wrap"><nav aria-label="Dashboards">{nav}</nav></div></header><main class="wrap"><h1>{E(title)}</h1><p class="sub">{E(sub)}</p>{body}</main>'
            f'<footer><div class="wrap">{E(kpis_note)} Local preview, noindex, not published. Definitions: lab/docs/DATA-PLATFORM.md.</div></footer></body></html>')


def build_all(db_path, out_dir):
    con = db.connect(db_path)
    analytics._require_published(con)
    out = Path(out_dir); out.mkdir(parents=True, exist_ok=True)
    q = lambda s, **k: pd.read_sql_query(s, con, **k)
    cm = q("SELECT * FROM mart_company_month ORDER BY month")
    months = list(cm.month)
    last = months[-1]
    lm = q("SELECT * FROM mart_location_month")
    note = "All amounts are synthetic dollars from placeholder prices; margins use placeholder cost percentages; labor uses placeholder wages."
    tot = cm.sum(numeric_only=True)
    files = {}
    # 1 executive
    last12 = cm.tail(12)
    t = tiles([("Net sales, 24 months (synthetic)", usd(tot.net_cents, True)), ("Orders (synthetic)", f"{int(tot.orders):,}"), ("Average ticket (synthetic)", usd(tot.net_cents / tot.orders)),
               ("Gross margin (placeholder costs)", f"{tot.gross_margin_cents / tot.net_cents * 100:.1f}%"), ("Labor % of sales (placeholder wages)", f"{tot.labor_cost_cents / tot.net_cents * 100:.1f}%"),
               ("Loyalty member share of orders", f"{tot.member_orders / tot.orders * 100:.1f}%"), ("Active sites, last month", str(int(cm.iloc[-1].active_locations)))])
    body = t + "<h2>Trend</h2>" + line_chart("Net sales per month (synthetic dollars)", months, [("net sales", list(cm.net_cents / 100), C["gold"])], lambda v: f"${v / 1000:,.0f}k")
    body += line_chart("Orders per month", months, [("orders", list(cm.orders), C["herb"])]) + line_chart("Gross margin % and labor % of sales", months, [("gross margin", list(cm.gross_margin_pct * 100), C["gold"]), ("labor", list(cm.labor_pct_of_sales * 100), C["ind"])], lambda v: f"{v:.1f}%")
    body += line_chart("Active sites (a growing business, by construction)", months, [("sites", list(cm.active_locations), C["lime"])])
    body += "<h2>Last 12 months</h2>" + table(last12[["month", "active_locations", "orders", "net_cents", "avg_ticket_cents", "gross_margin_pct", "labor_pct_of_sales", "member_order_share"]].rename(columns={"net_cents": "net sales", "avg_ticket_cents": "avg ticket"}),
                                               {"net sales": lambda v: usd(v, True), "avg ticket": lambda v: usd(v), "gross_margin_pct": lambda v: f"{v * 100:.1f}%", "labor_pct_of_sales": lambda v: f"{v * 100:.1f}%", "member_order_share": lambda v: f"{v * 100:.1f}%", "orders": lambda v: f"{int(v):,}"})
    files["index.html"] = page("index.html", "Executive performance", f"Company view, {months[0]} to {last}. Scenario calendar, not real time.", body, "KPI: net sales = sum of order totals after discounts; gross margin = net sales minus placeholder COGS; labor % = placeholder-wage labor cost / net sales. " + note)
    # 2 stores
    w6 = lm[lm.month.isin(months[-6:])].groupby(["location_id", "format"]).agg(orders=("orders", "sum"), net=("net_cents", "sum"), labor=("labor_cost_cents", "sum"), waste=("waste_cost_cents", "sum"), q=("quality_events", "sum")).reset_index()
    d6 = q("SELECT location_id, sum(net_cents) n, sum(actual_labor_hours) h, sum(cogs_cents) c FROM mart_daily_location WHERE month >= ? GROUP BY 1", params=(months[-min(6, len(months))],))
    w6 = w6.merge(d6, on="location_id")
    w6["avg ticket"] = w6.net / w6.orders; w6["sales/labor hr"] = w6.n / w6.h; w6["labor %"] = w6.labor / w6.net; w6["waste % COGS"] = w6.waste / w6.c
    w6 = w6.sort_values("net", ascending=False)
    body = f"<h2>Last 6 months by site</h2>" + bar_chart("Net sales per labor hour (synthetic $)", [(r.location_id + " · " + r.format, r["sales/labor hr"] / 100) for _, r in w6.sort_values("sales/labor hr", ascending=False).iterrows()], lambda v: f"${v:,.0f}")
    body += table(w6[["location_id", "format", "orders", "net", "avg ticket", "sales/labor hr", "labor %", "waste % COGS", "q"]].rename(columns={"net": "net sales", "q": "quality events"}),
                  {"orders": lambda v: f"{int(v):,}", "net sales": lambda v: usd(v, True), "avg ticket": lambda v: usd(v), "sales/labor hr": lambda v: usd(v), "labor %": lambda v: f"{v * 100:.1f}%", "waste % COGS": lambda v: f"{v * 100:.1f}%", "quality events": lambda v: f"{int(v)}"})
    body += "<h2>Format comparison</h2>" + table(w6.groupby("format").agg(sites=("location_id", "count"), net=("net", "sum"), orders=("orders", "sum")).reset_index().rename(columns={"net": "net sales"}), {"net sales": lambda v: usd(v, True), "orders": lambda v: f"{int(v):,}"})
    files["stores.html"] = page("stores.html", "Store operations", f"Last six months ({months[-6]} to {last}). Sites that opened recently are still ramping by construction.", body, "Sales per labor hour = net sales / actual labor hours. " + note)
    # 3 products
    p = q("SELECT item_id, name, category, is_concept_sku, sum(units) units, sum(net_cents) net, sum(cogs_cents) cogs, sum(margin_cents) margin FROM mart_product_month GROUP BY 1,2,3,4 ORDER BY net DESC")
    p["margin %"] = p.margin / p.net
    p["name"] = [n + (" (concept SKU)" if c else "") for n, c in zip(p.name, p.is_concept_sku)]
    body = "<h2>Margin by product (placeholder costs)</h2>" + bar_chart("Gross margin % by product", [(r["name"], r["margin %"] * 100) for _, r in p.iterrows()], lambda v: f"{v:.1f}%", C["herb"])
    body += table(p[["name", "category", "units", "net", "margin", "margin %"]].rename(columns={"net": "net sales", "margin": "gross margin"}), {"units": lambda v: f"{int(v):,}", "net sales": lambda v: usd(v, True), "gross margin": lambda v: usd(v, True), "margin %": lambda v: f"{v * 100:.1f}%"})
    body += '<p class="note">Margins are driven by the placeholder cost percentages in ref_cost_assumptions (food 30%, beer 22%, non-alcoholic 15%, merchandise 45%); differences between products reflect those inputs, not a finding. Concept SKUs were never brewed or made.</p>'
    files["products.html"] = page("products.html", "Product profitability", "All products, all months.", body, "Margin = net sales minus units x placeholder unit cost. " + note)
    # 4 inventory & waste
    iw = q("SELECT ingredient, sum(waste_kg) kg, sum(waste_cost_cents) c FROM mart_inventory_waste GROUP BY 1 ORDER BY c DESC")
    mw = q("SELECT month, sum(waste_cost_cents) c, sum(waste_kg) kg FROM mart_inventory_waste GROUP BY 1 ORDER BY 1")
    sw = q("SELECT location_id, sum(waste_cost_cents) w, sum(cogs_cents) c FROM mart_daily_location GROUP BY 1 ORDER BY 1")
    qe = q("SELECT event_type, severity, count(*) n FROM fact_quality_event GROUP BY 1,2 ORDER BY n DESC")
    body = "<h2>Waste</h2>" + line_chart("Waste cost per month (placeholder ingredient costs)", list(mw.month), [("waste cost", list(mw.c / 100), C["hib"])], lambda v: f"${v:,.0f}")
    body += bar_chart("Waste cost by ingredient (synthetic $)", [(r.ingredient, r.c / 100) for _, r in iw.iterrows()], lambda v: f"${v:,.0f}", C["hib"])
    body += bar_chart("Waste cost as % of COGS by site", [(r.location_id, r.w / r.c * 100) for _, r in sw.iterrows()], lambda v: f"{v:.2f}%", C["gold"])
    body += "<h2>Quality events</h2>" + table(qe.rename(columns={"n": "events"}))
    inv = q("SELECT count(*) n, count(DISTINCT location_key) sites, min(date_key) a, max(date_key) b FROM fact_inventory_count").iloc[0]
    body += f'<p class="note">Inventory: {int(inv.n):,} weekly counts across {int(inv.sites)} sites. Counts are simulated from volume, so a days-of-cover or variance view is not offered: the simulation does not model usage against stock.</p>'
    files["inventory.html"] = page("inventory.html", "Inventory and waste", "Waste cost, waste intensity and quality events.", body, "Waste cost = kg wasted x placeholder cost per kg. " + note)
    # 5 loyalty
    mat = analytics.cohort_matrix(con)
    seg_df, seg = analytics.rfm_segments(con)
    fun = analytics.loyalty_funnel(con)
    freq = analytics.purchase_frequency(con)
    body = tiles([("Loyalty profiles (fictional)", f"{fun['members']:,}"), ("Placed at least one order", f"{fun['ever_ordered']:,}"), ("First order within 30 days of joining", f"{fun['first_order_within_30d_rate'] * 100:.1f}%"),
                  ("Second order within 60 days of the first", f"{(fun['second_order_rate'] or 0) * 100:.1f}%")])
    body += line_chart("Member share of orders", months, [("member orders / orders", list(cm.member_order_share * 100), C["gold"])], lambda v: f"{v:.1f}%")
    body += "<h2>Cohort retention</h2><p class='sub'>Share of each join-month cohort that ordered in each later month (m+0 is the join month).</p>" + heatmap("Retention by join month", mat.head(24))
    body += "<h2>Segments (RFM tertiles)</h2>" + table(seg.reset_index(), {"members": lambda v: f"{int(v):,}", "avg_spend_cents": lambda v: usd(v)})
    body += "<h2>Purchase frequency</h2>" + bar_chart("Members by number of orders", [(r.orders_per_member, r.members) for r in freq.itertuples()], lambda v: f"{v:,.0f}", C["herb"])
    body += f'<p class="note">{E(fun["note"])} Segments describe behaviour in the synthetic data; they are not predictions.</p>'
    files["loyalty.html"] = page("loyalty.html", "Customer loyalty and retention", "Fictional members only (no names or contact data exist).", body, "Retention = active members in month / cohort size. " + note)
    # 6 merch
    mm = q("SELECT * FROM mart_merch_month ORDER BY month, item_id")
    body = tiles([("Merchandise net sales, 24 months (synthetic)", usd(mm.net_cents.sum(), True)), ("Units (synthetic)", f"{int(mm.units.sum()):,}"), ("Returns", f"{int(mm.returns.sum()):,}"), ("Return rate", f"{mm.returns.sum() / mm.units.sum() * 100:.1f}%")])
    pv = mm.pivot(index="month", columns="name", values="units").fillna(0)
    body += line_chart("Units per month by concept SKU", list(pv.index), [(n, list(pv[n]), c) for n, c in zip(pv.columns, [C["gold"], C["ind"], C["herb"]])])
    body += table(mm.groupby("name").agg(units=("units", "sum"), net=("net_cents", "sum"), returns=("returns", "sum")).reset_index().rename(columns={"net": "net sales"}), {"units": lambda v: f"{int(v):,}", "net sales": lambda v: usd(v, True)})
    body += '<p class="note">These are concept products (Hoodie 01 The Courtyard, Hoodie 02 Two Worlds, a graphic tee). None has been made or sold; sales here exist only inside the simulation. Merchandise is sold only at merch-selling sites.</p>'
    files["merch.html"] = page("merch.html", "Merchandise performance", "Concept merchandise in the synthetic enterprise.", body, "Return rate = returned lines / units. " + note)
    # 7 experiments
    base = float(q("SELECT 1.0*sum(n>=2)/count(*) r FROM (SELECT member_key, count(*) n FROM fact_order WHERE member_key IS NOT NULL GROUP BY 1)").iloc[0].r)
    port = experiments.run_portfolio(min(max(base, 0.05), 0.95))
    promo = analytics.promotion_analysis(con)
    adopt = analytics.concept_sku_adoption(con)
    body = '<h2>Experiment portfolio (simulated outcomes with a known injected effect)</h2><p class="sub">Five experiments, reported as they came out, including the inconclusive, the harmful and the invalid one.</p>'
    body += table(pd.DataFrame([{"id": x["id"], "experiment": x["title"], "n (treat/control)": f"{x['n_treatment']:,} / {x['n_control']:,}", "true effect": f"{x['injected_effect'] * 100:+.1f} pts", "observed": f"{x['observed_diff'] * 100:+.2f} pts",
                                 "95% CI": f"{x['ci95'][0] * 100:+.2f} to {x['ci95'][1] * 100:+.2f}", "p": x["p"], "SRM p": x["srm_p"], "verdict": x["verdict"]} for x in port]))
    body += f'<p class="note">Baseline metric: share of members with at least two orders ({base * 100:.1f}%), used as a stand-in for a 30-day repeat rate. Outcomes are simulated from that baseline; none of this is customer behaviour.</p>'
    pr = [{"promo": x["promo"], "name": x["name"].replace("Synthetic ", ""), "treated / control orders": f"{x['treated_orders']:,} / {x['control_orders']:,}", "gross ticket difference": f"{x['gross_ticket_diff_cents'] / 100:+.2f} $",
           "95% CI ($)": f"{x['ci95_cents'][0] / 100:+.2f} to {x['ci95_cents'][1] / 100:+.2f}", "p": x["p"], "discount given": usd(x["discount_given_cents"], True), "reading": "no detectable lift; discount is pure cost" if x["p"] >= 0.05 else "difference detected"}
          for x in promo if "treated_orders" in x]
    body += "<h2>Promotion analysis (within-window comparison)</h2>" + table(pd.DataFrame(pr))
    body += '<p class="note">The simulator assigns promotions at random but models no behavioural response, so a null lift in basket size is the expected result. What is real inside the simulation is the discount given.</p>'
    body += "<h2>Concept SKU presence in synthetic orders</h2>" + table(adopt) + '<p class="note">These shares come straight from the popularity weights chosen for the simulation, so they are inputs, not evidence of demand. Concept SKUs were never brewed, made or sold.</p>'
    files["experiments.html"] = page("experiments.html", "Product experiments and promotions", "Experimentation foundations: honest outcomes, including those that did not work.", body, "SRM = sample-ratio mismatch (chi-square against the planned split, alpha 0.001). " + note)
    for f, s in files.items():
        (out / f).write_text(s)
    (out / "experiment-results.json").write_text(json.dumps({"portfolio": port, "promotions": promo, "funnel": fun, "baseline_repeat_share": base}, indent=1, default=str))
    con.close()
    return sorted(files)


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--db", required=True); ap.add_argument("--out", required=True)
    a = ap.parse_args(argv)
    print(build_all(a.db, a.out))
    return 0


if __name__ == "__main__":
    sys.exit(main())
